import java.util.Scanner;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int americanoPrice = sc.nextInt();
        int americanoQty = sc.nextInt();
        int lattePrice = sc.nextInt();
        int latteQty = sc.nextInt();

        int supplyPrice = (americanoPrice * americanoQty) + (lattePrice * latteQty);
        int vat = (int) (supplyPrice * 0.1);
        int totalAmount = supplyPrice + vat;

        System.out.println("=== 스타카페 주문 영수증 ===");
        System.out.printf("아메리카노 (%d원 x %d잔): %d원\n", americanoPrice, americanoQty, americanoPrice * americanoQty);
        System.out.printf("카페라떼 (%d원 x %d잔): %d원\n", lattePrice, latteQty, lattePrice * latteQty);
        System.out.println("---------------------------------");
        System.out.printf("공급가액: %d원\n", supplyPrice);
        System.out.printf("부가세(10%%): %d원\n", vat);
        System.out.printf("최종 결제 금액: %d원\n", totalAmount);
    }
}

hint:
1. 4개의 정수를 sc.nextInt()로 순서대로 입력받습니다:
   int americanoPrice = sc.nextInt(); int americanoQty = sc.nextInt();
   int lattePrice = sc.nextInt(); int latteQty = sc.nextInt();
2. 부가세는 공급가액의 10%이며, 소수점을 버리고 정수로 변환하기 위해 (int) (supplyPrice * 0.1) 형태로 명시적 형변환을 적용합니다.
3. System.out.printf() 서식 출력에서 % 기호 자체를 출력할 때는 %% 로 두 번 작성해야 합니다.

