import java.util.Scanner;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int basePrice = sc.nextInt();
        int age = sc.nextInt();
        boolean isSpecial = sc.nextInt() == 1;
        boolean hasPass = sc.nextInt() == 1;

        double discountRate = hasPass ? 1.0 : ((isSpecial || age >= 65) ? 0.5 : (age < 13 ? 0.3 : 0.0));
        int finalPrice = basePrice - (int)(basePrice * discountRate);

        System.out.println("=== 에버드림 테마파크 티켓 발권기 ===");
        System.out.printf("기준 요금: %,d원\n", basePrice);
        System.out.printf("입장객 나이: %d세\n", age);
        System.out.printf("우대 혜택 적용: %s\n", isSpecial ? "적용 (우대 대상)" : "미적용");
        System.out.printf("연간 회원 여부: %s\n", hasPass ? "연간회원 (무료)" : "일반 고객");
        System.out.println("---------------------------------");
        System.out.printf("최종 결제 금액: %,d원 (할인율: %.0f%%)\n", finalPrice, discountRate * 100);
    }
}

hint:
1. 4개 입력값을 순서대로 받습니다: 기준요금(int), 나이(int), 우대여부(int), 연간회원여부(int)
2. 0 또는 1로 주어지는 우대 및 회원 여부를 논리형(boolean)으로 변환하면 가독성이 좋습니다:
   boolean isSpecial = sc.nextInt() == 1;
   boolean hasPass = sc.nextInt() == 1;
3. 조건문(if)을 아직 배우지 않은 1일차이므로 삼항 연산자 (조건 ? 참 : 거짓)를 중첩하여 할인율을 계산합니다:
   double discountRate = hasPass ? 1.0 : ((isSpecial || age >= 65) ? 0.5 : (age < 13 ? 0.3 : 0.0));
4. 최종 금액 = basePrice - (int)(basePrice * discountRate)

