import java.util.Scanner;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int basePrice = sc.nextInt();
        int age = sc.nextInt();
        boolean isMorning = sc.nextInt() == 1;
        boolean hasTelecomDiscount = sc.nextInt() == 1;

        double ageDiscountRate = (age >= 65) ? 0.5 : ((age < 19) ? 0.3 : 0.0);
        int priceAfterAge = basePrice - (int)(basePrice * ageDiscountRate);
        int priceAfterMorning = isMorning ? (priceAfterAge - 2000) : priceAfterAge;
        int finalPrice = hasTelecomDiscount ? (int)(priceAfterMorning * 0.9) : priceAfterMorning;

        System.out.println("=== CGV 영화 예매 요금 계산서 ===");
        System.out.printf("기준 요금: %,d원\n", basePrice);
        System.out.printf("관람자 나이: %d세 (연령 할인율: %.0f%%)\n", age, ageDiscountRate * 100);
        System.out.printf("조조 할인 적용 여부: %s (-2,000원)\n", isMorning ? "적용" : "미적용");
        System.out.printf("통신사 제휴 할인: %s (추가 10%%)\n", hasTelecomDiscount ? "적용" : "미적용");
        System.out.println("---------------------------------");
        System.out.printf("최종 결제 금액: %,d원\n", finalPrice);
    }
}

hint:
1. 4개 입력값을 순서대로 받습니다: 기준요금, 나이, 조조할인여부(1/0), 통신사할인여부(1/0)
2. 1단계 (나이 할인율 판별):
   double ageDiscountRate = (age >= 65) ? 0.5 : ((age < 19) ? 0.3 : 0.0);
   int priceAfterAge = basePrice - (int)(basePrice * ageDiscountRate);
3. 2단계 (조조 2,000원 차감):
   int priceAfterMorning = isMorning ? (priceAfterAge - 2000) : priceAfterAge;
4. 3단계 (통신사 제휴 10% 추가 할인):
   int finalPrice = hasTelecomDiscount ? (int)(priceAfterMorning * 0.9) : priceAfterMorning;

