import java.util.Scanner;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long latency = sc.nextLong();

        String layer;
        String status;

        if (latency <= 1) {
            layer = "L1 캐시 (L1 Cache)";
            status = "초고속 캐시 히트";
        } else if (latency <= 10) {
            layer = "L2/L3 캐시 (L2/L3 Cache)";
            status = "캐시 히트";
        } else if (latency <= 100) {
            layer = "메인 메모리 (DRAM RAM)";
            status = "캐시 미스 (메모리 접근)";
        } else if (latency <= 100000) {
            layer = "초고속 SSD (NVMe Storage)";
            status = "스토리지 I/O";
        } else {
            layer = "하드디스크 / 원격 네트워크 (Disk / Network)";
            status = "고지연 I/O 발생";
        }

        System.out.println("=== 메모리 계층 접근 분석표 ===");
        System.out.printf("소요 지연 시간: %dns\n", latency);
        System.out.printf("데이터 위치: %s\n", layer);
        System.out.printf("접근 상태 판정: %s\n", status);
    }
}

logic_guide:
📘 [단계별 로직 구성 순서 & 초보자 가이드]
1단계: Scanner로 지연 시간 입력받기
   Scanner sc = new Scanner(System.in);
   long latency = sc.nextLong();

2단계: 다중 조건문 if - else if - else 작성 (반드시 가장 빠른 작은 값부터 순서대로 검사!)
   String layer;
   String status;
   if (latency <= 1) {
       layer = "L1 캐시 (L1 Cache)";
       status = "초고속 캐시 히트";
   } else if (latency <= 10) {
       layer = "L2/L3 캐시 (L2/L3 Cache)";
       status = "캐시 히트";
   } else if (latency <= 100) {
       layer = "메인 메모리 (DRAM RAM)";
       status = "캐시 미스 (메모리 접근)";
   } else if (latency <= 100000) {
       layer = "초고속 SSD (NVMe Storage)";
       status = "스토리지 I/O";
   } else {
       layer = "하드디스크 / 원격 네트워크 (Disk / Network)";
       status = "고지연 I/O 발생";
   }
   (주의: 만약 latency <= 100000 을 맨 위에 두면 1ns도 100000 이하에 걸려버리는 논리 오류가 발생하므로, 작은 값부터 순차적으로 필터링해야 합니다!)

3단계: 서식 맞춤 출력
