import java.util.Scanner;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int code = sc.nextInt();

        String message;
        String action;

        switch (code) {
            case 200:
                message = "200 OK";
                action = "요청이 성공적으로 처리되었습니다.";
                break;
            case 201:
                message = "201 Created";
                action = "새로운 리소스가 정상 생성되었습니다.";
                break;
            case 400:
                message = "400 Bad Request";
                action = "잘못된 요청 구문 또는 유효하지 않은 파라미터입니다.";
                break;
            case 401:
                message = "401 Unauthorized";
                action = "인증 자격 증명이 유효하지 않거나 누락되었습니다.";
                break;
            case 403:
                message = "403 Forbidden";
                action = "접근 권한이 없는 보호된 리소스입니다.";
                break;
            case 404:
                message = "404 Not Found";
                action = "요청한 경로의 리소스를 찾을 수 없습니다.";
                break;
            case 500:
                message = "500 Internal Server Error";
                action = "서버 내부 처리 중 예기치 않은 오류가 발생했습니다.";
                break;
            default:
                message = "UNKNOWN STATUS";
                action = "정의되지 않은 HTTP 상태 코드입니다.";
                break;
        }

        System.out.println("=== HTTP 응답 라우팅 결과 ===");
        System.out.printf("상태 코드: %d\n", code);
        System.out.printf("응답 메시지: %s\n", message);
        System.out.printf("처리 안내: %s\n", action);
    }
}

