            status = "[EMERGENCY] 긴급 조치 - 즉각적인 리소스 확보가 필요합니다.";
        } else if (cpu >= 85 || mem >= 85 || disk <= 15) {
            status = "[CRITICAL] 위험 경보 - 관리자 점검이 필요합니다.";
        } else if (cpu >= 70 || mem >= 70 || disk <= 30) {
            status = "[WARNING] 주의 관찰 - 리소스 사용량을 모니터링하세요.";
        } else {
            status = "[NORMAL] 정상 운영 - 모든 리소스가 안정적입니다.";
        }

        System.out.println("=== 서버 리소스 상태 진단 보고서 ===");
        System.out.printf("CPU 사용률: %d%% | 메모리 사용률: %d%% | 디스크 잔여량: %dGB\n", cpu, mem, disk);
        System.out.printf("종합 판정: %s\n", status);
    }
}

