import java.util.Scanner;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int p1 = sc.nextInt();
        int p2 = sc.nextInt();
        int q = sc.nextInt();

        System.out.println("=== CPU 라운드 로빈 스케줄링 시뮬레이션 ===");
        int turn = 0;

        while (p1 > 0 || p2 > 0) {
            if (p1 > 0) {
                turn++;
                int exec = Math.min(p1, q);
                p1 -= exec;
                if (p1 == 0) {
                    System.out.printf("[턴 %d] P1 실행 (%dms 처리, P1 완료!)\n", turn, exec);
                } else {
                    System.out.printf("[턴 %d] P1 실행 (%dms 처리, 남은 작업: %dms)\n", turn, exec, p1);
                }
            }

            if (p2 > 0) {
                turn++;
                int exec = Math.min(p2, q);
                p2 -= exec;
                if (p2 == 0) {
                    System.out.printf("[턴 %d] P2 실행 (%dms 처리, P2 완료!)\n", turn, exec);
                } else {
                    System.out.printf("[턴 %d] P2 실행 (%dms 처리, 남은 작업: %dms)\n", turn, exec, p2);
                }
            }
        }

        System.out.println("-----------------------------------------");
        System.out.printf("총 실행 턴: %d턴 | 모든 프로세스 처리 완료\n", turn);
    }
}

