                dropped++;
                System.out.printf("[요청 %d] DROP: 429 Too Many Requests (필요: %d | 잔여: %d)\n", i, cost, tokens);
            }
        }

        System.out.println("---------------------------------");
        System.out.printf("처리 요약: 허용 %d건 / 차단 %d건\n", allowed, dropped);
    }
}

