import java.util.Scanner;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        int balance = 0;
        int pending = 0;
        boolean inTx = false;
        int commitCount = 0;
        int rollbackCount = 0;

        for (int i = 0; i < n; i++) {
            String cmd = sc.next();
            if (cmd.equals("BEGIN")) {
                inTx = true;
                pending = 0;
            } else if (cmd.equals("ADD")) {
                int val = sc.nextInt();
                if (inTx) pending += val;
                else balance += val;
            } else if (cmd.equals("SUB")) {
                int val = sc.nextInt();
                if (inTx) pending -= val;
                else balance -= val;
            } else if (cmd.equals("COMMIT")) {
                if (inTx) {
                    balance += pending;
                    pending = 0;
                    inTx = false;
                    commitCount++;
                }
            } else if (cmd.equals("ROLLBACK")) {
                if (inTx) {
                    pending = 0;
                    inTx = false;
                    rollbackCount++;
                }
            }
        }

        System.out.println("=== WAL 트랜잭션 실행 보고서 ===");
        System.out.printf("최종 계정 잔액: %d원\n", balance);
        System.out.printf("커밋 완료: %d회 | 롤백 취소: %d회\n", commitCount, rollbackCount);
    }
}

