        if (calculatedChecksum == receivedChecksum) {
            System.out.println("상태: [PASS] 데이터 무결성 검증 성공 (Packet OK)");
        } else {
            System.out.println("상태: [FAIL] 패킷 손상 감지 (Data Corrupted)");
        }
    }
}

