import java.util.Scanner;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        int r0 = 0;
        int r1 = 0;
        int cycles = 0;
        boolean halted = false;

        for (int i = 0; i < n; i++) {
            String op = sc.next();
            cycles++;

            if (op.equals("HALT")) {
                halted = true;
                break;
            } else if (op.equals("SET")) {
                String reg = sc.next();
                int val = sc.nextInt();
                if (reg.equals("R0")) r0 = (val % 256 + 256) % 256;
                else if (reg.equals("R1")) r1 = (val % 256 + 256) % 256;
            } else if (op.equals("ADD")) {
                sc.next(); sc.next();
                r0 = (r0 + r1) % 256;
            } else if (op.equals("SUB")) {
                sc.next(); sc.next();
                r0 = (r0 - r1 + 256) % 256;
            } else if (op.equals("MUL")) {
                sc.next(); sc.next();
                r0 = (r0 * r1) % 256;
            } else if (op.equals("SWAP")) {
                int tmp = r0;
                r0 = r1;
                r1 = tmp;
            }
        }

        System.out.println("=== 8비트 가상 CPU 실행 보고서 ===");
        System.out.printf("실행된 명령어 사이클: %d사이클\n", cycles);
        System.out.printf("최종 R0 레지스터: %d\n", r0);
        System.out.printf("최종 R1 레지스터: %d\n", r1);
        System.out.printf("CPU 상태: %s\n", halted ? "정상 정지 (HALT)" : "명령어 소진 완료");
    }
}

