import java.util.Scanner;
import java.util.ArrayList;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[][] seats = new int[4][5];
        int totalEmpty = 0;

        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 5; j++) {
                seats[i][j] = sc.nextInt();
                if (seats[i][j] == 0) totalEmpty++;
            }
        }

        int k = sc.nextInt();
        ArrayList<Integer> validRows = new ArrayList<>();

        for (int i = 0; i < 4; i++) {
            int consecutive = 0;
            boolean found = false;
            for (int j = 0; j < 5; j++) {
                if (seats[i][j] == 0) {
                    consecutive++;
                    if (consecutive >= k) {
                        found = true;
                        break;
                    }
                } else {
                    consecutive = 0;
                }
            }
            if (found) {
                validRows.add(i + 1);
            }
        }

        System.out.println("=== CGV 좌석 배정 분석 보고서 ===");
        System.out.printf("총 좌석 수: 20석 (빈 좌석: %d석, 예약됨: %d석)\n", totalEmpty, 20 - totalEmpty);
        System.out.printf("예약 희망 인원: %d명\n", k);
        System.out.println("---------------------------------");
        if (validRows.isEmpty()) {
            System.out.println("연속 좌석 예약 가능 행: 예약 불가");
        } else {
            StringBuilder sb = new StringBuilder();
            for (int idx = 0; idx < validRows.size(); idx++) {
                sb.append(validRows.get(idx)).append("행");
                if (idx < validRows.size() - 1) sb.append(", ");
            }
            System.out.printf("연속 좌석 예약 가능 행: %s\n", sb.toString());
        }
    }
}

