import java.util.Scanner;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[][] matrix = new int[n][n];

        // 우, 하, 좌, 상 방향 벡터
        int[] dr = {0, 1, 0, -1};
        int[] dc = {1, 0, -1, 0};

        int r = 0, c = 0, dir = 0;
        for (int val = 1; val <= n * n; val++) {
            matrix[r][c] = val;
            int nr = r + dr[dir];
            int nc = c + dc[dir];

            if (nr < 0 || nr >= n || nc < 0 || nc >= n || matrix[nr][nc] != 0) {
                dir = (dir + 1) % 4;
                nr = r + dr[dir];
                nc = c + dc[dir];
            }
            r = nr;
            c = nc;
        }

        System.out.printf("=== %dx%d 달팽이 소용돌이 배열 ===\n", n, n);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                System.out.printf("%2d", matrix[i][j]);
                if (j < n - 1) System.out.print(" ");
            }
            System.out.println();
        }

        int centerR = n / 2;
        int centerC = n / 2;
        int centerVal = matrix[centerR][centerC];

        int diagonalSum = 0;
        for (int i = 0; i < n; i++) {
            diagonalSum += matrix[i][i];
            if (i != n - 1 - i) {
                diagonalSum += matrix[i][n - 1 - i];
            }
        }

        System.out.println("---------------------------------");
        System.out.printf("중심 좌표 (%d행 %d열) 원소: %d\n", centerR + 1, centerC + 1, centerVal);
        System.out.printf("대각선(X자) 원소 합계: %d\n", diagonalSum);
    }
}

