import java.util.Scanner;

class Account {
    String owner;
    int balance;

    public Account(String owner, int balance) {
        this.owner = owner;
        this.balance = balance;
    }

    public boolean transferTo(Account target, int amount) {
        int fee = Math.max(500, (int) (amount * 0.01));
        int totalNeeded = amount + fee;

        if (this.balance < totalNeeded) {
            int shortage = totalNeeded - this.balance;
            System.out.printf("[이체 실패] 잔액 부족으로 이체 트랜잭션이 취소되었습니다. (부족액: %,d원)\n", shortage);
            return false;
        }

        this.balance -= totalNeeded;
        target.balance += amount;

        System.out.printf("[이체 요청] %s -> %s (송금액: %,d원 | 이체 수수료: %,d원)\n",
                this.owner, target.owner, amount, fee);
        System.out.println(">> 이체 트랜잭션 승인 완료!");
        return true;
    }
}

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String senderName = sc.next();
        int senderBal = sc.nextInt();
        String receiverName = sc.next();
        int receiverBal = sc.nextInt();
        int transferAmt = sc.nextInt();

        Account sender = new Account(senderName, senderBal);
        Account receiver = new Account(receiverName, receiverBal);

        System.out.println("=== 은행 계좌 간 이체 트랜잭션 시스템 ===");
        boolean success = sender.transferTo(receiver, transferAmt);
        System.out.println("---------------------------------");
        int fee = Math.max(500, (int) (transferAmt * 0.01));
        int deducted = success ? (transferAmt + fee) : 0;
        int received = success ? transferAmt : 0;

        System.out.printf("[출금 계좌] 예금주: %s | 차감액: %,d원 | 최종 잔액: %,d원\n",
                sender.owner, deducted, sender.balance);
        System.out.printf("[입금 계좌] 예금주: %s | 수취액: %,d원 | 최종 잔액: %,d원\n",
                receiver.owner, received, receiver.balance);
    }
}

