class Rectangle extends Shape {
    double w, h;

    public Rectangle(double w, double h) {
        this.w = w;
        this.h = h;
    }

    @Override
    double area() {
        return w * h;
    }

    @Override
    double perimeter() {
        return 2 * (w + h);
    }
}

class Circle extends Shape {
    double r;

    public Circle(double r) {
        this.r = r;
    }

    @Override
    double area() {
        return r * r * 3.14;
    }

    @Override
    double perimeter() {
        return 2 * 3.14 * r;
    }
}

