import java.util.Scanner;

abstract class Hero {
    String job;
    public Hero(String job) { this.job = job; }
    abstract int attack();
}

class Warrior extends Hero {
    public Warrior() { super("전사"); }
    @Override int attack() { return 200; }
}

class Rogue extends Hero {
    public Rogue() { super("도적"); }
    @Override int attack() { return 300; } // 150 * 2
}

class Healer extends Hero {
    public Healer() { super("힐러"); }
    @Override int attack() { return 80; }
}

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int bossHp = sc.nextInt();

        Hero[] party = { new Warrior(), new Rogue(), new Healer() };

        System.out.println("=== 던전 레이드 턴제 전투 시뮬레이션 ===");
        System.out.printf("보스 체력: %,d HP | 파티 인원: %d명\n", bossHp, party.length);
        System.out.println("---------------------------------");

        int turn = 0;
        int currentHp = bossHp;

        while (currentHp > 0) {
            turn++;
            int turnDamage = 0;
            for (Hero h : party) {
                turnDamage += h.attack();
            }

            currentHp = Math.max(0, currentHp - turnDamage);
            System.out.printf("[%d턴] 파티 총 공격: %,d 데미지 -> 보스 잔여 체력: %,d HP\n", turn, turnDamage, currentHp);
        }

        System.out.println("---------------------------------");
        System.out.printf("전투 승리! [%d턴] 만에 보스를 토벌하였습니다.\n", turn);
        System.out.println("생존 영웅: 전사, 도적, 힐러 (전원 생존)");
    }
}

