import java.util.Scanner;

class InsufficientBalanceException extends Exception {
    public InsufficientBalanceException(String message) {
        super(message);
    }
}

public class Solution {
    public static void withdraw(int balance, int amount) throws InsufficientBalanceException {
        if (amount > balance) {
            int shortage = amount - balance;
            throw new InsufficientBalanceException(String.format("출금 불가 - 잔액이 %,d원 부족합니다.", shortage));
        }
        int newBalance = balance - amount;
        System.out.printf("[출금 완료] %,d원 출금 성공 (남은 잔액: %,d원)\n", amount, newBalance);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int balance = sc.nextInt();
        int amount = sc.nextInt();

        System.out.println("=== 국민은행 스마트 ATM ===");
        System.out.printf("현재 계좌 잔액: %,d원\n", balance);
        System.out.printf("출금 요청 금액: %,d원\n", amount);

        try {
            withdraw(balance, amount);
        } catch (InsufficientBalanceException e) {
            System.out.println("[예외 감지] InsufficientBalanceException 발생!");
            System.out.printf("사유: %s\n", e.getMessage());
            System.out.println("거래가 안전하게 취소되었습니다.");
        }
    }
}

