import java.util.Scanner;

class InvalidOrderException extends Exception {
    public InvalidOrderException(String message) {
        super(message);
    }
}

interface Payable {
    void processPayment();
}

interface Shippable {
    void assignDelivery();
}

class DeliveryOrder implements Payable, Shippable {
    String customer;
    int amount;
    int distanceKm;

    public DeliveryOrder(String customer, int amount, int distanceKm) throws InvalidOrderException {
        if (amount < 15000) {
            throw new InvalidOrderException(String.format("최소 주문 금액(15,000원) 미달입니다. (현재 금액: %,d원)", amount));
        }
        this.customer = customer;
        this.amount = amount;
        this.distanceKm = distanceKm;
    }

    @Override
    public void processPayment() {
        System.out.printf("[결제 승인] Payable: %,d원 결제가 정상 승인되었습니다.\n", amount);
    }

    @Override
    public void assignDelivery() {
        int estimatedTime = distanceKm * 5;
        System.out.printf("[배송 연계] Shippable: 배달 라이더 배차 완료 (예상 배달 소요시간: %d분)\n", estimatedTime);
    }
}

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String customer = sc.next();
        int amount = sc.nextInt();
        int distance = sc.nextInt();

        System.out.println("=== 배달의민족 주문 접수 파이프라인 ===");
        try {
            DeliveryOrder order = new DeliveryOrder(customer, amount, distance);
            System.out.printf("[주문 검증] 주문자: %s | 주문 금액: %,d원 | 배송 거리: %dkm\n",
                    order.customer, order.amount, order.distanceKm);
            order.processPayment();
            order.assignDelivery();
            System.out.println("주문 처리가 성공적으로 완료되었습니다.");
        } catch (InvalidOrderException e) {
            System.out.println("[주문 거절] 유효하지 않은 주문입니다.");
            System.out.printf("사유: %s\n", e.getMessage());
        }
    }
}

