import java.util.Scanner;

class NetworkTimeoutException extends Exception {
    public NetworkTimeoutException(String msg) { super(msg); }
}

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String errorType = sc.next();
        int amount = sc.nextInt();
        int point = sc.nextInt();

        System.out.println("=== 결제 게이트웨이 복구 엔진 ===");
        System.out.printf("주문 금액: %,d원 | 사용 포인트: %,d원\n", amount, point);

        int maxRetries = 3;
        boolean paymentSuccess = false;

        for (int attempt = 1; attempt <= maxRetries; attempt++) {
            try {
                if ("PG_TIMEOUT".equals(errorType)) {
                    throw new NetworkTimeoutException("PG사 응답 시간 초과");
                }
                paymentSuccess = true;
                break;
            } catch (NetworkTimeoutException e) {
                if (attempt < maxRetries) {
                    System.out.printf("[%d차 시도 실패] NetworkTimeoutException 감지 -> %d회차 재시도...\n", attempt, attempt);
                } else {
                    System.out.printf("[%d차 시도 실패] NetworkTimeoutException 감지 -> 재시도 한도 초과!\n", attempt);
                }
            }
        }

        System.out.println("---------------------------------");
        if (!paymentSuccess) {
            System.out.printf("[보상 트랜잭션 가동] 결제 실패로 사용된 포인트 %,dP를 원상 복구합니다.\n", point);
            System.out.println("최종 결제 결과: 트랜잭션 롤백 완료");
        } else {
            System.out.println("최종 결제 결과: 결제 정상 승인 완료");
        }
    }
}

