public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        ArrayList<String> originalList = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            originalList.add(sc.next());
        }
        int k = sc.nextInt();

        ArrayList<String> filteredList = new ArrayList<>();
        for (String word : originalList) {
            if (word.length() >= k) {
                filteredList.add(word);
            }
        }

        Collections.sort(filteredList);

        System.out.println("=== 단어 필터링 및 정렬 결과 ===");
        System.out.printf("입력 단어 수: %d개 (필터 기준: %d자 이상)\n", n, k);
        System.out.printf("필터링 및 정렬된 단어: %s\n", filteredList);
        System.out.printf("추출된 단어 수: %d개\n", filteredList.size());
    }
}

