import java.util.Scanner;
import java.util.LinkedHashMap;
import java.util.Map;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        LinkedHashMap<String, Integer> scoreMap = new LinkedHashMap<>();

        for (int i = 0; i < n; i++) {
            String name = sc.next();
            int score = sc.nextInt();
            scoreMap.put(name, score);
        }

        System.out.println("=== 학급 성적부 관리 시스템 (Map) ===");
        System.out.printf("등록 학생 수: %d명\n", n);

        int total = 0;
        int maxScore = -1;
        String topStudent = "";

        for (Map.Entry<String, Integer> entry : scoreMap.entrySet()) {
            String name = entry.getKey();
            int score = entry.getValue();
            System.out.printf("- %s: %d점\n", name, score);
            total += score;
            if (score > maxScore) {
                maxScore = score;
                topStudent = name;
            }
        }

        double avg = (double) total / n;
        System.out.println("---------------------------------");
        System.out.printf("학급 평균 점수: %.2f점\n", avg);
        System.out.printf("최고 득점자: %s (%d점)\n", topStudent, maxScore);
    }
}

