        this.name = name;
        this.category = category;
        this.price = price;
    }
}

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        List<Product> products = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            products.add(new Product(sc.next(), sc.next(), sc.nextInt()));
        }

        System.out.println("=== Stream API 상품 데이터 분석 보고서 ===");
        System.out.printf("전체 상품 수: %d개\n", n);
        System.out.println("---------------------------------");

        List<Product> electroList = products.stream()
                .filter(p -> "전자기기".equals(p.category))
                .toList();

        int electroSum = electroList.stream()
                .mapToInt(p -> p.price)
                .sum();

        double electroAvg = electroList.stream()
                .mapToInt(p -> p.price)
                .average()
                .orElse(0.0);

        System.out.println("[전자기기 카테고리 분석]");
        System.out.printf("- 해당 상품 수: %d개\n", electroList.size());
        System.out.printf("- 총 금액 합계: %,d원\n", electroSum);
        System.out.printf("- 평균 단가: %,.2f원\n", electroAvg);
        System.out.println("---------------------------------");

        long premiumCount = products.stream()
                .filter(p -> p.price >= 50000)
                .count();

        System.out.printf("[50,000원 이상 프리미엄 상품 수]: %d개\n", premiumCount);
    }
}

