import java.util.Scanner;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

class LogEntry {
    int status;
    String url;
    int duration;

    public LogEntry(int status, String url, int duration) {
        this.status = status;
        this.url = url;
        this.duration = duration;
    }
}

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        List<LogEntry> logs = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            logs.add(new LogEntry(sc.nextInt(), sc.next(), sc.nextInt()));
        }

        long errorCount = logs.stream()
                .filter(l -> l.status >= 400)
                .count();

        long successCount = n - errorCount;
        double errorRate = ((double) errorCount / n) * 100;

        Map<String, Long> urlCounts = logs.stream()
                .collect(Collectors.groupingBy(l -> l.url, Collectors.counting()));

        Map.Entry<String, Long> topUrl = urlCounts.entrySet().stream()
                .max(Map.Entry.comparingByValue())
                .orElse(null);

        double avgSuccessDuration = logs.stream()
                .filter(l -> l.status >= 200 && l.status < 300)
                .mapToInt(l -> l.duration)
                .average()
                .orElse(0.0);

        System.out.println("=== 서버 접속 로그 스트림 분석 보고서 ===");
        System.out.printf("총 수집 로그: %d건\n", n);
        System.out.println("---------------------------------");
        System.out.printf("[응답 상태 분석] 정상(2xx): %d건 | 에러(4xx/5xx): %d건 (에러율: %.1f%%)\n",
                successCount, errorCount, errorRate);
        if (topUrl != null) {
            System.out.printf("[최다 호출 엔드포인트] %s (%d회 호출)\n", topUrl.getKey(), topUrl.getValue());
        }
        System.out.printf("[정상 응답 평균 처리시간] %.2fms\n", avgSuccessDuration);
    }
}

