const fs = require('fs');
const lines = fs.readFileSync(0, 'utf-8').trim().split('\n').map(l => l.trim()).filter(Boolean);
if (lines.length === 0) process.exit(0);

const [nStr, targetId, newQtyStr] = lines[0].split(/\s+/);
const n = parseInt(nStr, 10);
const newQty = parseInt(newQtyStr, 10);

const cart = [];
for (let i = 1; i <= n; i++) {
    const [id, name, qty] = lines[i].split(/\s+/);
    cart.push({ id, name, quantity: parseInt(qty, 10) });
}

const updatedCart = cart.map(item => {
    if (item.id === targetId) {
        return { ...item, quantity: Math.max(1, newQty) };
    }
    return item;
});

const updatedItem = updatedCart.find(item => item.id === targetId);
const totalQty = updatedCart.reduce((sum, item) => sum + item.quantity, 0);

console.log('수량 변경 완료:', updatedItem);
console.log(`장바구니 총 담긴 수량: ${totalQty}개`);

