if (lines.length === 0) process.exit(0);

const [tier, amountStr] = lines[0].split(/\s+/);
const amount = parseInt(amountStr, 10);

const tierPolicy = {
    VIP: { discountRate: 0.15, pointRate: 0.05 },
    GOLD: { discountRate: 0.10, pointRate: 0.03 },
    SILVER: { discountRate: 0.05, pointRate: 0.01 },
    BRONZE: { discountRate: 0.00, pointRate: 0.01 }
};

const policy = tierPolicy[tier] || tierPolicy.BRONZE;
const discount = Math.floor(amount * policy.discountRate);
const finalPrice = amount - discount;
const point = Math.floor(finalPrice * policy.pointRate);

console.log('=== 멤버십 혜택 정산서 ===');
console.log(`고객 등급: ${tier}`);
console.log(`결제 원금: ${amount.toLocaleString()}원`);
console.log(`등급 할인: -${discount.toLocaleString()}원`);
console.log(`최종 결제 금액: ${finalPrice.toLocaleString()}원`);
console.log(`적립 포인트: ${point.toLocaleString()}P`);

