const fs = require('fs');
const lines = fs.readFileSync(0, 'utf-8').trim().split('\n').map(l => l.trim()).filter(Boolean);
if (lines.length === 0) process.exit(0);

const [coupon, nStr] = lines[0].split(/\s+/);
const n = parseInt(nStr, 10);

let subtotal = 0;
for (let i = 1; i <= n; i++) {
    const [price, qty] = lines[i].split(/\s+/).map(Number);
    subtotal += price * qty;
}

let discount = 0;
if (coupon === 'FIXED_5000') {
    discount = 5000;
} else if (coupon === 'PERCENT_10') {
    discount = Math.floor(subtotal * 0.1);
}
discount = Math.min(discount, subtotal);

const discountedSubtotal = subtotal - discount;
const shippingFee = (discountedSubtotal >= 50000) ? 0 : 3000;
const totalPayment = discountedSubtotal + shippingFee;

console.log('=== 주문 최종 결제 확인서 ===');
console.log(`주문 상품 합계: ${subtotal.toLocaleString()}원`);
console.log(`쿠폰 적용 할인: -${discount.toLocaleString()}원 (${coupon})`);
console.log(`배송비: ${shippingFee === 0 ? '무료 (50,000원 이상 구매)' : shippingFee.toLocaleString() + '원'}`);
console.log('---------------------------------');
console.log(`최종 결제 금액: ${totalPayment.toLocaleString()}원`);

