solution:
const fs = require('fs');
const lines = fs.readFileSync(0, 'utf-8').trim().split('\n').map(l => l.trim()).filter(Boolean);
if (lines.length === 0) process.exit(0);

class LRUCache {
    constructor(capacity) {
        this.capacity = capacity;
        this.cache = new Map();
    }

    get(key) {
        if (!this.cache.has(key)) return -1;
        const val = this.cache.get(key);
        this.cache.delete(key);
        this.cache.set(key, val);
        return val;
    }

    put(key, val) {
        if (this.cache.has(key)) {
            this.cache.delete(key);
        } else if (this.cache.size >= this.capacity) {
            const oldestKey = this.cache.keys().next().value;
            this.cache.delete(oldestKey);
        }
        this.cache.set(key, val);
    }
}

const [capStr, nStr] = lines[0].split(/\s+/);
const lru = new LRUCache(parseInt(capStr, 10));
const n = parseInt(nStr, 10);

console.log(`=== LRU 캐시 시뮬레이터 (용량: ${capStr}) ===`);
for (let i = 1; i <= n; i++) {
    const parts = lines[i].split(/\s+/);
    const cmd = parts[0];
    if (cmd === 'PUT') {
        lru.put(parts[1], parts[2]);
        console.log(`PUT ${parts[1]}=${parts[2]} -> 캐시상태: [${Array.from(lru.cache.keys()).join(', ')}]`);
    } else if (cmd === 'GET') {
        const res = lru.get(parts[1]);
        console.log(`GET ${parts[1]} -> ${res}`);
    }
}
